package glitch

import data.glitch_lib

# Helper to check if a specific string contains an insecure protocol URL
contains_insecure_protocol_str(str) {
    regex.match("(?i)^(http|ftp|telnet|smtp)://", str)
}

# Helper to check a Value node for insecure protocol URLs
contains_insecure_protocol(val) {
    # Direct string check
    val.ir_type == "String"
    contains_insecure_protocol_str(val.value)
} else {
    # Check inside Sum (concatenation) or complex strings
    walk(val, [_, node])
    node.ir_type == "String"
    contains_insecure_protocol_str(node.value)
}

# Helper to check for insecure SSL/TLS configurations (values indicating disabled/none/no)
is_insecure_ssl_value(val) {
    val.ir_type == "Boolean"
    val.value == false
} else {
    val.ir_type == "String"
    regex.match("(?i)^(none|disabled|false|no|0|disable|disable\\s+ssl)$", val.value)
} else {
    # Check inside complex values
    walk(val, [_, node])
    node.ir_type == "String"
    regex.match("(?i)^(none|disabled|false|no|0|disable|disable\\s+ssl)$", node.value)
}

# Detect insecure protocols in Ansible variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    v := vars[_]
    contains_insecure_protocol(v.value)

    result := {
        "type": "sec_https",
        "element": v,
        "path": parent.path,
        "description": "Use of unencrypted protocol - Data transmitted over unencrypted channels may be intercepted. (CWE-319)"
    }
}

# Detect insecure protocols in atomic unit attributes (Ansible, Chef, Puppet)
